#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "trmm.h"


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;
  for (i = 0; i < m; i++) {
    for (j = 0; j < i; j++) {
      A[i][j] = (DATA_TYPE)((i+j) % m)/m;
    }
    A[i][i] = 1.0;
    for (j = 0; j < n; j++) {
      B[i][j] = (DATA_TYPE)((n+(i-j)) % n)/n;
    }
 }

}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("B");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, B[i][j]);
    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_trmm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /*
   * Create restrict-qualified local views of the 2D arrays.
   *
   * POLYBENCH_2D(...) in a function parameter list becomes a VLA-based
   * pointer type (e.g., DATA_TYPE A[m][m]). Inside the function, it
   * decays to `DATA_TYPE (*)[m]`. We bind that to explicit `restrict`
   * pointers so the compiler can assume:
   *   - A_ and B_ do not alias each other.
   *   - Different rows of B_ do not alias.
   *
   * This greatly helps auto-vectorization of the innermost loop.
   */
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE (*restrict B_)[n] = B;

//BLAS parameters
//SIDE   = 'L'
//UPLO   = 'L'
//TRANSA = 'T'
//DIAG   = 'U'
// => Form  B := alpha*A**T*B.
// A is MxM
// B is MxN
#pragma scop
  /*
   * Original kernel (for reference):
   *
   * for (i = 0; i < _PB_M; i++)
   *   for (j = 0; j < _PB_N; j++) {
   *     for (k = i+1; k < _PB_M; k++)
   *       B[i][j] += A[k][i] * B[k][j];
   *     B[i][j] = alpha * B[i][j];
   *   }
   *
   * This performs a triangular matrix-matrix multiply using a column-wise
   * accumulation (k is inner, j is middle). The innermost access to B[k][j]
   * is strided in memory, which is unfriendly to caches and SIMD.
   *
   * Optimized version below:
   *
   *  - We keep `i` as the outermost loop to preserve the dependence pattern:
   *      * Row i reads from rows k > i (as B[k][*]) and writes only B[i][*].
   *      * Row k is updated only when i == k, so all required reads of
   *        B[k][*] for i < k happen before B[k][*] is ever modified.
   *
   *  - We interchange the `j` and `k` loops so that `j` becomes the
   *    innermost loop, giving unit-stride accesses along the row of B.
   *    For each pair (i,k), we perform a rank-1 style update:
   *
   *        B[i][:] += A[k][i] * B[k][:]
   *
   *    which streams efficiently over both rows `B[i][:]` and `B[k][:]`.
   *
   *  - We then scale row i by `alpha` in a separate, vectorizable pass.
   *
   * The resulting computation is algebraically identical to the original.
   */
  for (i = 0; i < _PB_M; i++)
  {
    /* Triangular update: accumulate contributions from rows k > i into row i. */
    for (k = i + 1; k < _PB_M; k++)
    {
      DATA_TYPE a_ki = A_[k][i];

      /* Row pointers to enable efficient, unit-stride access in j. */
      DATA_TYPE *restrict Bi = &B_[i][0];
      const DATA_TYPE *restrict Bk = &B_[k][0];

      /* Tell the compiler there are no loop-carried dependencies in j. */
      #pragma GCC ivdep
      for (j = 0; j < _PB_N; j++)
      {
        Bi[j] += a_ki * Bk[j];
      }
    }

    /* Scale the entire row i by alpha. This matches:
       B[i][j] = alpha * ( B[i][j]_original + sum_{k>i} A[k][i] * B[k][j]_original )
     */
    DATA_TYPE *restrict Bi = &B_[i][0];

    #pragma GCC ivdep
    for (j = 0; j < _PB_N; j++)
    {
      Bi[j] = alpha * Bi[j];
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trmm (m, n, alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(B)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
