  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("B");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, B[i][j]);
    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_trmm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  /* Use the PolyBench loop bounds (may differ from raw m/n when
     instrumented) and keep them in local consts so the compiler can
     treat them as loop-invariant. */
  const int Mdim = _PB_M;
  const int Ndim = _PB_N;

  /* Create local aliases with 'restrict' and assumed alignment.
     - 'restrict' tells the compiler that A_ and B_ do not alias, which
       enables more aggressive reordering and vectorization.
     - The alignment assumption matches PolyBench's aligned allocator
       (polybench_alloc_data). If POLYBENCH_ALIGNMENT is changed to be
       smaller than 32 bytes, this value should be reduced accordingly. */
  DATA_TYPE (* restrict A_)[m] =
    (DATA_TYPE (*)[m])__builtin_assume_aligned((void*)A, 32);
  DATA_TYPE (* restrict B_)[n] =
    (DATA_TYPE (*)[n])__builtin_assume_aligned((void*)B, 32);

  int i, j, k;
  const DATA_TYPE alpha_local = alpha;

  // BLAS parameters
  // SIDE   = 'L'
  // UPLO   = 'L'
  // TRANSA = 'T'
  // DIAG   = 'U'
  // => Form  B := alpha*A**T*B.
  // A is MxM
  // B is MxN

  /* The original code was:
       for (i)
         for (j) {
           for (k = i+1 .. M-1)
             B[i][j] += A[k][i] * B[k][j];
           B[i][j] = alpha * B[i][j];
         }

     This reorders the inner loops to improve data locality and
     vectorization while preserving the per-element operation order:

       - For a fixed row i and column j, the sequence of updates in k is
         still in ascending k, followed by a single multiplication by
         alpha, exactly as in the original code.
       - The new structure performs, for each (i,k) pair, a DAXPY-like
         operation on entire rows:
             B[i, :] += A[k][i] * B[k, :]

     Both B[i, :] and B[k, :] are contiguous in memory inside the
     innermost loop, which improves cache behavior and allows the
     compiler to generate efficient SIMD code.
  */

#pragma scop
  for (i = 0; i < Mdim; ++i)
  {
    /* Pointer to row i of B for faster access. */
    DATA_TYPE * restrict Bi = B_[i];

    /* Accumulate A^T * B contributions into row i:
         Bi[:] += A_[k][i] * B_[k][:]
       for all k > i. */
    for (k = i + 1; k < Mdim; ++k)
    {
      const DATA_TYPE aik = A_[k][i];          /* Reused across all columns. */
      const DATA_TYPE * restrict Bk = B_[k];   /* Row k of B. */

      /* DAXPY-like inner kernel: Bi[j] += aik * Bk[j].  */
#pragma GCC ivdep
      for (j = 0; j < Ndim; ++j)
      {
        Bi[j] += aik * Bk[j];
      }
    }

    /* Scale the updated row i by alpha:
         Bi[:] *= alpha
       This is separated to keep the arithmetic on Bi in a simple,
       vectorizable loop. */
#pragma GCC ivdep
    for (j = 0; j < Ndim; ++j)
    {
      Bi[j] *= alpha_local;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trmm (m, n, alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(B)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
