/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Original BLAS parameters
     SIDE   = 'L'
     UPLO   = 'L'
     TRANSA = 'T'
     DIAG   = 'U'
   => Form  B := alpha * A**T * B.

   Optimization overview:
   - Reorder loops from (i, j, k) to (i, k, j).  For a fixed (i,k),
     A[k][i] is now loaded once and reused across all columns j,
     instead of being reloaded for every (i,j) pair.
   - Inner-most loop iterates over j so that both B[i][j] and B[k][j]
     are accessed with unit stride, enabling efficient cache usage and
     SIMD vectorization.
   - Split the scaling B[i][j] = alpha * B[i][j] into a separate loop
     executed after all updates to row i; this preserves the original
     mathematical result while improving vectorization.
   - Optional OpenMP parallelization across columns of B.  Each thread
     gets a disjoint block of columns, so there are no cross-thread
     dependencies and no extra memory is required.
*/
static
void kernel_trmm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Help the compiler with aliasing: POLYBENCH_2D expands to a VLA
     pointer type.  We capture it in restrict-qualified pointers. */
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE (*restrict B_)[n] = B;

  /* PolyBench uses _PB_M/_PB_N as possibly-tuned loop bounds
     (<= m,n).  Use local constants for clarity. */
  const int mm = _PB_M;
  const int nn = _PB_N;

//BLAS parameters
//SIDE   = 'L'
//UPLO   = 'L'
//TRANSA = 'T'
//DIAG   = 'U'
// => Form  B := alpha*A**T*B.
// A is MxM
// B is MxN
#pragma scop
#if defined(_OPENMP)
  /* Parallel version: split columns of B among threads.
     For each thread, j in [j_start, j_end) is private; all
     computations for those columns are local to that thread.  */
  #pragma omp parallel
  {
    int tid = omp_get_thread_num();
    int nt  = omp_get_num_threads();

    /* Static partition of columns [0, nn) into nearly equal blocks. */
    int j_start = (tid * nn) / nt;
    int j_end   = ((tid + 1) * nn) / nt;

    for (i = 0; i < mm; i++)
    {
      /* Accumulate contributions from rows k > i into row i. */
      for (k = i + 1; k < mm; k++)
      {
        DATA_TYPE aik = A_[k][i]; /* single load, reused across all j */

        /* Inner-most loop: contiguous access over columns of rows i and k.
           No loop-carried dependencies across j, so it is safe to SIMD. */
        #pragma omp simd
        for (j = j_start; j < j_end; j++)
        {
          B_[i][j] += aik * B_[k][j];
        }
      }

      /* Scale row i by alpha (only this thread's column block). */
      #pragma omp simd
      for (j = j_start; j < j_end; j++)
      {
        B_[i][j] *= alpha;
      }
    }
  }
#else
  /* Sequential version (no OpenMP): same computation order in (i,k) as
     above, operating over all columns [0, nn). */
  for (i = 0; i < mm; i++)
  {
    for (k = i + 1; k < mm; k++)
    {
      DATA_TYPE aik = A_[k][i];

      /* Vectorizable inner loop: unit-stride access in B_[i][j] and B_[k][j]. */
      #pragma omp simd
      for (j = 0; j < nn; j++)
      {
        B_[i][j] += aik * B_[k][j];
      }
    }

    #pragma omp simd
    for (j = 0; j < nn; j++)
    {
      B_[i][j] *= alpha;
    }
  }
#endif
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trmm (m, n, alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(B)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
