    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, B[i][j]);
    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_trmm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Alias the variable-size arrays with restrict-qualified pointers.
     This makes the lack of aliasing between A and B explicit and helps
     the compiler generate better vectorized code. */
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE (*restrict B_)[n] = B;

//BLAS parameters
//SIDE   = 'L'
//UPLO   = 'L'
//TRANSA = 'T'
//DIAG   = 'U'
// => Form  B := alpha*A**T*B.
// A is MxM
// B is MxN
#pragma scop
  /* ------------------------------------------------------------------
   * Stage 1: Compute B := A^T * B (without the final scaling by alpha).
   *
   * Original reference code (simplified):
   *   for i
   *     for j
   *       for k = i+1..M-1
   *         B[i][j] += A[k][i] * B[k][j];
   *       B[i][j] *= alpha;
   *
   * For each (i,j), the contributions from k = i+1..M-1 are accumulated
   * in increasing k order, and only then is B[i][j] scaled by alpha.
   *
   * We transform the triple loop to improve data locality:
   *
   *   for k = 1..M-1
   *     for i = 0..k-1
   *       B[i][:] += A[k][i] * B[k][:]
   *
   * i.e., we loop over k (source row of B) first, then i (destination
   * rows), and keep j innermost. For each fixed k, B[k][:] is accessed
   * with unit stride and reused while updating all rows i < k. A[k][i]
   * is taken from row k of A, also with unit-stride access in i.
   *
   * For any given element B[i][j], the sequence of arithmetic operations
   * remains identical:
   *   - it is read as a source (B[k][j]) only while still equal to its
   *     original value (for i' < i, k == i),
   *   - then receives additions for k = i+1..M-1 in increasing k order,
   *   - finally it is multiplied by alpha (in Stage 2).
   * ------------------------------------------------------------------ */
  for (k = 1; k < _PB_M; ++k)
  {
    const DATA_TYPE *restrict Bk = B_[k];

    for (i = 0; i < k; ++i)
    {
      const DATA_TYPE a_ki = A_[k][i];
      DATA_TYPE *restrict Bi = B_[i];

      /* Inner-most loop: rank-1 update on row i using row k.
         Accesses Bi[j] and Bk[j] with unit stride, ideal for SIMD. */
      #pragma omp simd
      for (j = 0; j < _PB_N; ++j)
      {
        Bi[j] += a_ki * Bk[j];
      }
    }
  }

  /* ------------------------------------------------------------------
   * Stage 2: Scale B by alpha, i.e., B := alpha * B.
   *
   * In the reference implementation, each element B[i][j] is multiplied
   * by alpha immediately after all its k-contributions are accumulated.
   * No other iteration ever reads a scaled value of B as a source.
   *
   * By postponing all scalings to this separate pass, we still guarantee
   * that every use of B[k][j] as a source in Stage 1 sees the original,
   * unscaled value, and every B[i][j] is finally multiplied by alpha
   * exactly once. Thus the numerical result is identical.
   * ------------------------------------------------------------------ */
  for (i = 0; i < _PB_M; ++i)
  {
    DATA_TYPE *restrict Bi = B_[i];

    #pragma omp simd
    for (j = 0; j < _PB_N; ++j)
    {
      Bi[j] *= alpha;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trmm (m, n, alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(B)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
